import { defineConfig, globalIgnores } from "eslint/config";
import nextVitals from "eslint-config-next/core-web-vitals";

export default defineConfig([
  ...nextVitals,
  globalIgnores([".next/**", "out/**", "build/**", "next-env.d.ts"]),
]);

let lastEdit = null;

function inputSelection() {
  const target = document.activeElement;
  if (!(target instanceof HTMLTextAreaElement || target instanceof HTMLInputElement)) return null;
  const start = target.selectionStart ?? 0;
  const end = target.selectionEnd ?? start;
  if (end <= start) return null;
  return { kind: "input", target, start, end, text: target.value.slice(start, end) };
}

function richSelection() {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0 || selection.isCollapsed) return null;
  const range = selection.getRangeAt(0);
  const host = range.commonAncestorContainer.nodeType === Node.ELEMENT_NODE
    ? range.commonAncestorContainer
    : range.commonAncestorContainer.parentElement;
  const editable = host?.closest?.('[contenteditable="true"]');
  return { kind: editable ? "contenteditable" : "readonly", range: range.cloneRange(), text: selection.toString(), editable };
}

function currentSelection() {
  return inputSelection() || richSelection();
}

function replaceSelection(replacement) {
  const selection = currentSelection();
  if (!selection || !selection.text) return { ok: false, reason: "Select text in an editable field first." };

  if (selection.kind === "input") {
    const { target, start, end } = selection;
    lastEdit = { kind: "input", target, start, replacementLength: replacement.length, original: selection.text };
    target.setRangeText(replacement, start, end, "end");
    target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertReplacementText", data: replacement }));
    return { ok: true };
  }

  if (selection.kind === "contenteditable" && selection.editable) {
    const htmlBefore = selection.editable.innerHTML;
    const range = selection.range;
    range.deleteContents();
    range.insertNode(document.createTextNode(replacement));
    selection.editable.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertReplacementText", data: replacement }));
    lastEdit = { kind: "contenteditable", target: selection.editable, htmlBefore };
    return { ok: true };
  }

  return { ok: false, reason: "The selected text is read-only. Use Copy result instead." };
}

function undoLast() {
  if (!lastEdit) return { ok: false, reason: "There is no in-page edit to undo." };

  if (lastEdit.kind === "input" && document.contains(lastEdit.target)) {
    const end = lastEdit.start + lastEdit.replacementLength;
    lastEdit.target.setRangeText(lastEdit.original, lastEdit.start, end, "end");
    lastEdit.target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "historyUndo" }));
    lastEdit = null;
    return { ok: true };
  }

  if (lastEdit.kind === "contenteditable" && document.contains(lastEdit.target)) {
    lastEdit.target.innerHTML = lastEdit.htmlBefore;
    lastEdit.target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "historyUndo" }));
    lastEdit = null;
    return { ok: true };
  }

  lastEdit = null;
  return { ok: false, reason: "The edited element is no longer available." };
}

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (message?.type === "selection") {
    const selection = currentSelection();
    sendResponse(selection ? { ok: true, text: selection.text, editable: selection.kind !== "readonly" } : { ok: false, reason: "Select some text first." });
    return;
  }
  if (message?.type === "replace") {
    sendResponse(replaceSelection(String(message.text || "")));
    return;
  }
  if (message?.type === "undo") {
    sendResponse(undoLast());
  }
});

{
  "manifest_version": 3,
  "name": "Provenance Cleaner Safe Editor",
  "version": "0.1.0",
  "description": "Protected in-place editing with purpose, intensity, deterministic preservation, and one-step undo.",
  "permissions": [
    "storage",
    "activeTab",
    "clipboardWrite"
  ],
  "host_permissions": [
    "https://provenance-cleaner.vercel.app/*",
    "http://localhost:3000/*"
  ],
  "action": {
    "default_popup": "popup.html",
    "default_title": "Provenance Cleaner"
  },
  "content_scripts": [
    {
      "matches": [
        "<all_urls>"
      ],
      "js": [
        "content.js"
      ],
      "run_at": "document_idle"
    }
  ]
}

const $ = (id) => document.getElementById(id);
const fields = ["apiKey", "apiBase", "mode", "intensity", "purpose"];

async function activeTab() {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  return tab;
}

function setStatus(message, error = false) {
  $("status").textContent = message;
  $("status").className = error ? "status error" : "status";
}

async function loadSettings() {
  const saved = await chrome.storage.local.get(fields);
  $("apiKey").value = saved.apiKey || "";
  $("apiBase").value = saved.apiBase || "https://provenance-cleaner.vercel.app";
  $("mode").value = saved.mode || "parity";
  $("intensity").value = saved.intensity || "balanced";
  $("purpose").value = saved.purpose || "general";
}

async function saveSettings() {
  const payload = Object.fromEntries(fields.map((id) => [id, $(id).value.trim()]));
  await chrome.storage.local.set(payload);
  setStatus("Settings saved. Content is not stored.");
}

async function sendToPage(message) {
  const tab = await activeTab();
  if (!tab?.id) throw new Error("No active tab.");
  return chrome.tabs.sendMessage(tab.id, message);
}

async function rewriteSelection() {
  setStatus("Reading selected text…");
  const selected = await sendToPage({ type: "selection" });
  if (!selected?.ok || !selected.text) throw new Error(selected?.reason || "Select text first.");
  if (selected.text.trim().length < 20) throw new Error("Select at least 20 characters.");

  const apiKey = $("apiKey").value.trim();
  if (!apiKey) throw new Error("Add a developer API key first.");
  const base = $("apiBase").value.trim().replace(/\/$/u, "");
  const body = {
    operationId: crypto.randomUUID(),
    text: selected.text,
    mode: $("mode").value,
    intensity: $("intensity").value,
    purpose: $("purpose").value,
  };

  setStatus("Running protected rewrite…");
  const response = await fetch(`${base}/api/v1/transform`, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${apiKey}` },
    body: JSON.stringify(body),
  });
  const payload = await response.json();
  if (!response.ok) throw new Error(payload?.error?.message || payload?.error || "Rewrite failed.");

  $("output").value = payload.text;
  $("outputBox").hidden = false;
  if (selected.editable) {
    const replaced = await sendToPage({ type: "replace", text: payload.text });
    if (!replaced?.ok) throw new Error(replaced?.reason || "Result was generated but could not be placed in the page.");
    setStatus(`Validated and replaced in page · ${payload.purpose}/${payload.intensity}. Undo is available.`);
  } else {
    setStatus("Validated result is ready. The original selection is read-only, so copy the result instead.");
  }
}

$("rewrite").addEventListener("click", () => rewriteSelection().catch((error) => setStatus(error.message, true)));
$("undo").addEventListener("click", () => sendToPage({ type: "undo" }).then((result) => {
  if (!result?.ok) throw new Error(result?.reason || "Could not undo.");
  setStatus("Last in-page rewrite undone.");
}).catch((error) => setStatus(error.message, true)));
$("save").addEventListener("click", () => saveSettings().catch((error) => setStatus(error.message, true)));
$("copy").addEventListener("click", () => navigator.clipboard.writeText($("output").value).then(() => setStatus("Result copied.")).catch(() => setStatus("Could not copy result.", true)));
void loadSettings();
